import{_ as s,o as t,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-4-reset-password/report3_spec.md","filePath":"feature/authentication/3-2-4-reset-password/report3_spec.md"}'),n={name:"feature/authentication/3-2-4-reset-password/report3_spec.md"};function i(a,e,l,d,g,u){return t(),r("div",null,[...e[0]||(e[0]=[o("<p><strong>3.2.4 Reset Password</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a user who forgot the password opens /forgot-password and submits an email address.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Unauthenticated USER who cannot sign in because the password is forgotten.</li><li><strong>Purpose</strong>: Restore access to the account by email through a single-use reset link, without revealing whether a given email is registered, and force sign-in again on every device once the password is changed.</li><li><strong>Interface</strong>: /forgot-password (email input) and /reset-password?token=... (new password + confirm password).</li><li><strong>Data Processing</strong>: forgot-password always returns 200 regardless of whether the email exists; if it exists, invalidates any earlier reset token, generates a new single-use token, and emails it. reset-password consumes the token atomically, hashes the new password, updates the last-password-change time, and writes an audit log entry.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Forgot Password / Reset Password screens:</p><ul><li>/forgot-password: email input, submit button. On success the form is replaced by a confirmation panel; the UI never says whether the email was actually found.</li><li>/reset-password: reads token from the URL; if absent, redirects to /forgot-password. New password input with strength meter, confirmation input, submit button.</li><li>Toasts: <strong>MSG15</strong> on forgot-password success (always), <strong>MSG16</strong>/<strong>MSG17</strong> on reset-password failure (invalid/expired vs. already-used token), <strong>MSG18</strong> on reset-password success, then redirected to /login.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: email (forgot-password step); token, newPassword (reset step).</li><li><strong>Input optional</strong>: confirmPassword — client-side check only, never sent to the server.</li><li><strong>System data</strong>: userId, email, passwordHash, lastPasswordChange, reset token (TTL up to 1 hour), reverse-index of the currently valid token per user.</li><li><strong>Output</strong>: no payload, 200, for both endpoints; the response never distinguishes success/failure cases that must stay silent.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-13</strong>: forgot-password always returns 200 whether or not the email exists. When it exists, any earlier token for that user is deleted first, then a new single-use token is generated with TTL up to 1 hour; only the most recently issued token is ever valid. reset-password with a missing/expired/superseded token -&gt; 400 RESET_TOKEN_INVALID; a token already consumed -&gt; 400 RESET_TOKEN_USED; a token for a deleted user -&gt; 400 RESET_TOKEN_INVALID.</li><li><strong>BR-02</strong>: New password must meet policy (min 8 characters, at least 1 digit); stored as a BCrypt hash.</li><li><strong>BR-12</strong>: After a successful reset, every refresh token issued before the change is rejected on its next use, forcing sign-in again on every device.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>email empty on /forgot-password -&gt; Display: <strong>MSG02</strong></li><li>email invalid format -&gt; Display: <strong>MSG04</strong></li><li>newPassword missing, under 8 characters, or missing a digit -&gt; Display: <strong>MSG05</strong></li><li>confirmPassword mismatch -&gt; Display: <strong>MSG06</strong></li><li>token missing from URL -&gt; client redirects to /forgot-password, no server call</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens /forgot-password and submits the email address.</li><li>The system looks up the account by normalized email.</li><li>If found, the system deletes any earlier reset token, generates a new single-use token, stores it with TTL up to 1 hour, and sends the reset email.</li><li>The endpoint returns 200 regardless of whether the account was found. Toast <strong>MSG15</strong>.</li><li>The user opens the reset link, lands on /reset-password?token=..., and enters the new password and confirmation.</li><li>The system resolves and atomically deletes the reset token, hashes and saves the new password, and writes an audit log entry.</li><li>The endpoint returns 200. Toast <strong>MSG18</strong>; the user is redirected to /login.</li><li>Every refresh token issued before this reset is rejected on its next use, forcing sign-in again on that device.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: email empty -&gt; Display: <strong>MSG02</strong>. 1.a2: The user fills in the field and resubmits.</li><li>1.b1: email invalid format -&gt; Display: <strong>MSG04</strong>. 1.b2: The user corrects the format and resubmits.</li><li>2.a1: Email does not match any account (BR-13) -&gt; still 200, toast <strong>MSG15</strong>, no email sent. 2.a2: The user checks the inbox.</li><li>6.a1: Token missing, expired, or superseded (BR-13) -&gt; 400 RESET_TOKEN_INVALID, toast <strong>MSG16</strong>. 6.a2: The user requests a new reset link.</li><li>6.b1: Token already consumed (BR-13) -&gt; 400 RESET_TOKEN_USED, toast <strong>MSG17</strong>. 6.b2: The user requests a new reset link.</li><li>6.c1: Token decodes to a deleted account -&gt; 400 RESET_TOKEN_INVALID, toast <strong>MSG16</strong>. 6.c2: The user requests a new reset link.</li><li>6.d1: newPassword fails the policy (BR-02) -&gt; Display: <strong>MSG05</strong>. 6.d2: The user corrects the password and resubmits.</li><li>6.e1: confirmPassword mismatch -&gt; Display: <strong>MSG06</strong>, submit blocked. 6.e2: The user re-types the confirmation.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>On a successful reset, passwordHash is replaced and lastPasswordChange is set; an audit log row exists; the consumed token and its reverse-index are deleted.</li><li>On any forgot-password call, exactly one valid reset token exists per account at a time; the response is always 200.</li><li>Refresh tokens issued before the reset are rejected on their next use (BR-12), independent of any explicit logout.</li></ul>",14)])])}const h=s(n,[["render",i]]);export{c as __pageData,h as default};
